export function exhibitionNarrationCue(exhibition, index) {
  if (index < 0) return exhibition.dek ? { key: 'entrance', section: 0, part: 'summary', focus: 'entrance' } : null;
  const step = exhibition.steps[index];
  if (!step) return null;
  const focus = `${step.roomIndex}/${step.stopIndex}`;
  if (step.kind === 'closing') return { key: 'closing', section: 'closing', part: '', focus: 'closing' };
  if (step.kind === 'introduction') return exhibition.rooms[step.roomIndex]?.introduction ? { key: `${step.sectionIndex}/intro`, section: step.sectionIndex, part: 'intro', focus } : null;
  if (step.kind === 'passage') return { key: `${step.sectionIndex}/${step.blockIndex}/${step.paragraph}`, section: step.sectionIndex, part: `${step.blockIndex}.${step.paragraph}`, focus };
  return null;
}

// The guide accompanies the visit. Camera movement, reading a work, opening
// notes, and opening the visit guide must leave the current recording alone.
// Only a language change or leaving the exhibition invalidates playback.
export function exhibitionNarrationBusy(state = {}) {
  return Boolean(
    state.translationLoading
    || state.leaving
  );
}

// Listening history belongs to this visit, with independent progress for each
// language. Revisited completed passages stay quiet until explicitly replayed.
export class ExhibitionListeningHistory {
  constructor() { this.passages = new Map(); }
  key(cue, language = '') { return `${language || 'original'}/${cue?.key || ''}`; }
  progress(cue, language) { return this.passages.get(this.key(cue, language)) || { time: 0, complete: false }; }
  remember(cue, language, time) {
    if (!cue || this.progress(cue, language).complete) return;
    this.passages.set(this.key(cue, language), { time, complete: false });
  }
  finish(cue, language) { this.passages.set(this.key(cue, language), { time: 0, complete: true }); }
  replay(cue, language) { this.passages.delete(this.key(cue, language)); }
}
